// fs.unlinkSync(asarPath);
// console.log('delete the original asar.');
// }
// await asar.createPackage(appPath, asarPath);
// fs.rmdirSync(appPath,{recursive:true});
// console.log('create new asar.');
}catch(err){
console.error(err);
}
}
*/afterSign.js*
